; console.log('Config: ' + metadataConfigPath); console.log('Output: ' + outputDir); if (dryRun) console.log('Mode: DRY RUN (no upload or submission)'); const metaModule = await import(resolve(metadataConfigPath)); const entries = metaModule.default; const primaryEntry = entries[0]; if (!primaryEntry || !primaryEntry.filename) { console.error('metadata config must have at least one entry with a filename.'); process.exit(1); } // Step 1: Validate console.log('\\n[1/7] Validating SVG...'); const validation = validate(absInput); report(validation, absInput); if (!validation.passed) { console.error('Validation failed. Fix the errors above before proceeding.'); process.exit(1); } // Step 2: Scale console.log('\\n[2/7] Scaling artboard to >=25 MP...'); const svgText = readFileSync(absInput, 'utf-8'); const scaleResult = scale(svgText, 25); let workingSvgPath = absInput; if (scaleResult.changed) { const scaledName = basename(absInput, '.svg') + '-scaled.svg'; workingSvgPath = join(outputDir, scaledName); writeFileSync(workingSvgPath, scaleResult.svg, 'utf-8'); console.log(' Scaled: ' + scaleResult.originalDims + ' (' + scaleResult.originalMP + ' MP) -> ' + scaleResult.newDims + ' (' + scaleResult.newMP + ' MP)'); } else { console.log(' Already ' + scaleResult.originalMP + ' MP - no scaling needed'); } // Step 3: Convert SVG -> AI console.log('\\n[3/7] Converting to .ai via Illustrator ExtendScript...'); const aiPath = join(outputDir, primaryEntry.filename); const convertResult = await convertToAi(workingSvgPath, aiPath); if (!convertResult.success) { console.error('Conversion failed: ' + convertResult.error); process.exit(1); } // Step 4: Inject Metadata console.log('\\n[4/7] Injecting XMP metadata into .ai...'); const injectResult = await injectMetadata(convertResult.aiPath, primaryEntry); if (!injectResult.success) { console.error('Metadata injection failed: ' + injectResult.error); process.exit(1); } // Step 5: Generate Metadata Files console.log('\\n[5/7] Writing metadata.csv and .metadata.txt...'); generateMetadata(entries, outputDir); // Step 6: Upload if (dryRun || skipUpload) { console.log('\\n[6/7] Upload - SKIPPED'); } else { console.log('\\n[6/7] Uploading to Adobe Stock SFTP...'); const uploadResult = await upload(convertResult.aiPath, { verbose: true }); if (!uploadResult.success) { console.error('Upload failed: ' + uploadResult.error); process.exit(1); } console.log(' Waiting 30s for file to appear in portal...'); await new Promise(r => setTimeout(r, 30000)); } // Step 7: Submit if (dryRun || skipSubmit) { console.log('\\n[7/7] Portal submission - SKIPPED'); } else { console.log('\\n[7/7] Submitting via contributor portal...'); const results = await submitToPortal(entries, { headless: true }); results.forEach(function(r) { console.log(' ' + (r.success ? 'OK' : 'FAIL') + ' ' + r.filename + (r.reason ? ' - ' + r.reason : '')); }); if (results.some(function(r) { return !r.success; })) process.exit(1); } console.log('\\n' + '='.repeat(60)); console.log('Pipeline complete'); console.log('Output: ' + outputDir); console.log('='.repeat(60) + '\\n'); } const args = process.argv.slice(2); const positional = args.filter(function(a) { return !a.startsWith('--'); }); if (!positional[0] || !positional[1]) { console.error('Usage: node src/pipeline.js <input.svg> <metadata-config.js> [--dry-run] [--skip-upload] [--skip-submit]'); process.exit(1); } await run(positional[0], positional[1], { dryRun: args.includes('--dry-run'), skipUpload: args.includes('--skip-upload'), skipSubmit: args.includes('--skip-submit'), }); ENDOFFILE"}),e(s,{children:"Now update validate.js to check for strokes, and update convert.js to expand them:"}),e(i,{children:"Edited a file"}),e(i,{children:'Ran grep -n "findTextElements" /home/claude/adobe-stock/src/tools/validate.js | head -5'}),e(i,{children:"Read /home/claude/adobe-stock/src/tools/validate.js"}),e(i,{children:`Ran # Add stroke detection function after findUnnamedLayers and add check in validate() # 